imright <- function(h1,h2){
  return(h1-h2==1)
}
 
nextto <- function(h1,h2){
  return(abs(h1-h2)==1)
}
 
house_with <- function(f,val){
  return(which(levels(f)==val))
}
 
for (i in seq(length(col_p))){
